  <script>
    const categories = ["Top", "Trending", "Watchlist", "Prediction Markets", "Most Visited", "New"];
    const networks = ["All Networks", "BSC", "Solana", "Base", "Ethereum", "More"];

    const baseCoins = [
      ["Bitcoin","BTC",75612.78,0.12,1.85,4.21,1.51e12,28.435e10,"20.01M BTC","Ethereum","Top"],
      ["Ethereum","ETH",2356.00,-0.08,2.14,6.01,2.84e11,14.883e10,"120.44M ETH","Ethereum","Top"],
      ["Tether","USDT",1.00,0.01,0.00,0.02,1.09e11,5.381e10,"109.2B USDT","Ethereum","Top"],
      ["BNB","BNB",612.45,0.22,1.44,2.85,8.91e10,2.2e9,"145.9M BNB","BSC","Trending"],
      ["Solana","SOL",144.78,0.35,3.72,10.84,6.91e10,4.7e9,"477.1M SOL","Solana","Trending"],
      ["USDC","USDC",1.00,0.00,0.01,-0.01,5.22e10,6.2e9,"52.2B USDC","Base","Top"],
      ["XRP","XRP",0.62,-0.12,1.23,7.52,3.55e10,1.8e9,"57.1B XRP","Ethereum","Most Visited"],
      ["Dogecoin","DOGE",0.182,0.42,2.21,9.18,2.66e10,1.1e9,"146.0B DOGE","Base","Watchlist"],
      ["Toncoin","TON",6.91,-0.32,-1.42,3.84,2.38e10,3.9e8,"3.47B TON","More","New"],
      ["Cardano","ADA",0.47,0.18,0.94,4.11,1.67e10,5.5e8,"35.4B ADA","BSC","Prediction Markets"]
    ];

    const allCoins = [];
    for (let i = 0; i < 100; i++) {
      const t = baseCoins[i % baseCoins.length];
      const factor = 1 + (i * 0.0075);
      const price = t[2] / (1 + (i%7)*0.09) * (1 + (i%5)*0.015);
      allCoins.push({
        rank: i + 1,
        name: i < 10 ? t[0] : `${t[0]} ${Math.floor(i/10)+1}`,
        symbol: t[1],
        price,
        h1: t[3] + ((i%5)-2)*0.11,
        h24: t[4] + ((i%7)-3)*0.39,
        d7: t[5] + ((i%9)-4)*0.71,
        mcap: t[6] / factor,
        volume: t[7] / (1 + (i%8)*0.2),
        supply: t[8],
        network: t[9],
        category: t[10],
      });
    }

    let activeCategory = "Top";
    let activeNetwork = "All Networks";
    let activePage = 1;
    const pageTotal = 84;
    const visibleColumns = { price:true, h1:true, h24:true, d7:true, mcap:true, vol:true, supply:true, spark:true };
    const filterState = { gainersOnly:false, volumeOver1B:false };

    const fmtUsd = n => `$${n.toLocaleString(undefined, { maximumFractionDigits: n > 10 ? 2 : 6 })}`;
    const fmtBig = n => {
      if (n >= 1e12) return `$${(n/1e12).toFixed(2)}T`;
      if (n >= 1e9) return `$${(n/1e9).toFixed(2)}B`;
      if (n >= 1e6) return `$${(n/1e6).toFixed(2)}M`;
      return `$${n.toLocaleString()}`;
    };
    const pct = n => `${n > 0 ? '+' : ''}${n.toFixed(2)}%`;

    function renderTabs() {
      const ct = document.getElementById('categoryTabs');
      const nt = document.getElementById('networkTabs');
      ct.innerHTML = categories.map(c => `<button class="tab ${c===activeCategory?'active':''}" data-cat="${c}">${c}</button>`).join('');
      nt.innerHTML = networks.map(n => `<button class="tab ${n===activeNetwork?'active':''}" data-net="${n}">${n}</button>`).join('');

      ct.querySelectorAll('button').forEach(btn => btn.onclick = () => { activeCategory = btn.dataset.cat; activePage = 1; renderAll(); });
      nt.querySelectorAll('button').forEach(btn => btn.onclick = () => { activeNetwork = btn.dataset.net; activePage = 1; renderAll(); });
    }

    function sparkPath(seed, up) {
      const pts = Array.from({length:24}, (_,i)=> Math.max(6, Math.min(30, 18 + Math.sin((i+seed)/3)*7 + (up? i*0.22 : -i*0.2))));
      return pts.map((y,i)=>`${i*5},${y}`).join(' ');
    }

    function renderTable() {
      const body = document.getElementById('tableBody');
      let rows = allCoins.filter(c => c.category === activeCategory || activeCategory === "Top" && c.rank <= 100);
      if (activeNetwork !== 'All Networks') rows = rows.filter(c => c.network === activeNetwork || (activeNetwork === 'More' && c.network === 'More'));
      if (filterState.gainersOnly) rows = rows.filter(c => c.h24 > 0);
      if (filterState.volumeOver1B) rows = rows.filter(c => c.volume > 1e9);

      rows = rows.slice(0, 100);

      const indexRow = `<tr class="index-row"><td class="num">—</td><td><div class="coin-name"><span class="coin-dot" style="background:#60a5fa"></span>CoinTracker 20 Index <span class="coin-sub">CT20</span></div></td>
      <td class="num col-price">$154.29</td><td class="num col-1h up">+0.21%</td><td class="num col-24h up">+1.15%</td><td class="num col-7d up">+4.97%</td>
      <td class="num col-mcap">$2.56T</td><td class="num col-vol">$156.9B</td><td class="num col-supply">—</td><td class="center col-spark"><svg class="spark" viewBox="0 0 120 34"><polyline fill="none" stroke="#16c784" stroke-width="2" points="${sparkPath(1,true)}"/></svg></td></tr>`;

      body.innerHTML = indexRow + rows.map(c => `
        <tr>
          <td class="num">${c.rank}</td>
          <td><div class="coin-name"><span class="coin-dot"></span>${c.name} <span class="coin-sub">${c.symbol}</span></div></td>
          <td class="num col-price">${fmtUsd(c.price)}</td>
          <td class="num col-1h ${c.h1>=0?'up':'down'}">${pct(c.h1)}</td>
          <td class="num col-24h ${c.h24>=0?'up':'down'}">${pct(c.h24)}</td>
          <td class="num col-7d ${c.d7>=0?'up':'down'}">${pct(c.d7)}</td>
          <td class="num col-mcap">${fmtBig(c.mcap)}</td>
          <td class="num col-vol">${fmtBig(c.volume)}</td>
          <td class="num col-supply">${c.supply}</td>
          <td class="center col-spark"><svg class="spark" viewBox="0 0 120 34"><polyline fill="none" stroke="${c.d7>=0?'#16c784':'#ea3943'}" stroke-width="2" points="${sparkPath(c.rank, c.d7>=0)}"/></svg></td>
        </tr>`).join('');

      document.getElementById('rowCount').textContent = rows.length.toString();
      Object.entries(visibleColumns).forEach(([k,v]) => {
        document.querySelectorAll(`.col-${k}`).forEach(el => el.style.display = v ? '' : 'none');
      });
    }

    function renderPagination() {
      const el = document.getElementById('pagination');
      const pages = [1,2,3,4,'...',84];
      el.innerHTML = pages.map(p => `<button class="page-btn ${p===activePage?'active':''}" data-p="${p}">${p}</button>`).join('');
      el.querySelectorAll('button').forEach(btn => btn.onclick = () => {
        const val = btn.dataset.p;
        if (val === '...') return;
        activePage = Number(val);
        renderPagination();
      });
    }

    function renderPanels() {
      const columnsPanel = document.getElementById('columnsPanel');
      const filtersPanel = document.getElementById('filtersPanel');

      const labels = [
        ['price','Price'],['1h','1h %'],['24h','24h %'],['7d','7d %'],['mcap','Market Cap'],['vol','Volume(24h)'],['supply','Circulating Supply'],['spark','7d Sparkline']
      ];
      columnsPanel.innerHTML = labels.map(([id,txt]) => {
        const key = id==='1h'?'h1':id==='24h'?'h24':id==='7d'?'d7':id;
        return `<label style="margin-right:14px; display:inline-flex; gap:6px; align-items:center;"><input type="checkbox" data-col="${key}" ${visibleColumns[key]?'checked':''}/> ${txt}</label>`;
      }).join('');
      columnsPanel.querySelectorAll('input').forEach(i => i.onchange = () => { visibleColumns[i.dataset.col] = i.checked; renderTable(); });

      filtersPanel.innerHTML = `
        <label style="margin-right:16px;"><input type="checkbox" id="gainersOnly" ${filterState.gainersOnly?'checked':''}/> 24h Gainers only</label>
        <label><input type="checkbox" id="volOver" ${filterState.volumeOver1B?'checked':''}/> Volume over $1B</label>`;
      document.getElementById('gainersOnly').onchange = e => { filterState.gainersOnly = e.target.checked; renderTable(); };
      document.getElementById('volOver').onchange = e => { filterState.volumeOver1B = e.target.checked; renderTable(); };
    }

    function renderAll() {
      renderTabs();
      renderPanels();
      renderTable();
      renderPagination();
    }

    document.getElementById('columnsBtn').onclick = () => document.getElementById('columnsPanel').classList.toggle('show');
    document.getElementById('filtersBtn').onclick = () => document.getElementById('filtersPanel').classList.toggle('show');

    document.getElementById('readMoreBtn').onclick = () => {
      const ex = document.getElementById('summaryExtra');
      ex.classList.toggle('show');
      document.getElementById('readMoreBtn').textContent = ex.classList.contains('show') ? 'Read Less' : 'Read More';
    };

    const slides = Array.from(document.querySelectorAll('.promo-slide'));
    let slideIdx = 0;
    const showSlide = i => slides.forEach((s,idx)=>s.classList.toggle('active', idx===i));
    const nextSlide = () => { slideIdx = (slideIdx + 1) % slides.length; showSlide(slideIdx); };
    document.getElementById('promoNext').onclick = nextSlide;
    document.getElementById('promoPrev').onclick = () => { slideIdx = (slideIdx - 1 + slides.length) % slides.length; showSlide(slideIdx); };
    setInterval(nextSlide, 4500);

    renderAll();
  </script>
</body>
